  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Amoxicillin, which shares the exact α-amino-p-hydroxyphenylacetamido side chain, has an absolute oral bioavailability of 79.7% at 1000 mg, demonstrating that this side chain supports efficient oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Cephradine, a close oral aminocephalosporin analogue, has a mean oral bioavailability of about 94% in young subjects, supporting high oral absorption for the query's cephem amino-acid structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cefoperazone, which shares the p-hydroxyphenyl side chain and a tetrazolylthiomethyl-type C3 substituent, has an oral bioavailability of approximately 40% in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Cefazolin has very low oral bioavailability (1.5–2%), but it lacks the free α-amino acid side chain that is the key intestinal absorption motif present in the query, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is cefatrizine, an oral aminocephalosporin with the amoxicillin/cefadroxil-type α-amino-p-hydroxyphenylacetamido side chain. High-oral-bioavailability analogues sharing this motif, plus the p-hydroxyphenyl/tetrazole-thiomethyl analogue cefoperazone (~40%), support F ≥ 20%; low-oral cefazolin lacks the critical amino-acid side chain and does not override this evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for cefatrizine is present in the provided records.",
    "The cefoperazone record is supportive but lacks the free α-amino group, making its transferability imperfect.",
    "Low-oral records such as cefazolin show that C3 tetrazole-thio substituents can be associated with poor absorption when the amino-acid side chain is absent, but not in the presence of the query's absorption motif."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

